<?php

namespace App\Entity;

use App\Enum\DocumentRetentionClass;
use Doctrine\DBAL\Types\Types;
use Doctrine\ORM\Mapping as ORM;

/**
 * H5a — a document generated by the application and attached to an email (planning PDFs).
 * Rendered ONCE, stored once, then referenced by id: the email message, the outbound
 * delivery and the activity timeline only ever carry a DocumentReference (id, type,
 * filename, sha256, size) — never the bytes. The bytes live here only, so "which PDF did
 * this person receive?" has an exact, verifiable answer (sha256) long after the send.
 *
 * Immutable: a document is never modified; a new rendering is a new row (or the same row,
 * when the content is byte-identical — see DocumentStore::store()).
 *
 * H5b (D-132) — retentionClass says what the document IS (IMMUTABLE_EVIDENCE: the bytes a
 * person received — never purged automatically); sourceKey + inputFingerprint identify WHAT
 * it represents (e.g. the personal planning of a person for a period, and a hash of the data
 * rendered): sending the same document again reuses these exact bytes instead of rendering a
 * new PDF from data that may have changed since.
 */
#[ORM\Entity]
#[ORM\Table(name: 'generated_document')]
#[ORM\Index(name: 'idx_generated_document_sha256', columns: ['sha256'])]
#[ORM\Index(name: 'idx_generated_document_source', columns: ['source_key', 'input_fingerprint'])]
class GeneratedDocument
{
    #[ORM\Id]
    #[ORM\GeneratedValue]
    #[ORM\Column]
    private ?int $id = null;

    #[ORM\Column(name: 'document_type', length: 40)]
    private string $documentType;

    #[ORM\Column(length: 255)]
    private string $filename;

    #[ORM\Column(length: 64, options: ['fixed' => true])]
    private string $sha256;

    #[ORM\Column(name: 'byte_size')]
    private int $byteSize;

    #[ORM\Column(name: 'content_type', length: 100)]
    private string $contentType;

    /** @var resource|string */
    #[ORM\Column(type: Types::BLOB, length: 4294967295)]
    private $content;

    #[ORM\Column(name: 'created_at')]
    private \DateTimeImmutable $createdAt;

    #[ORM\Column(name: 'retention_class', length: 32, enumType: DocumentRetentionClass::class, options: ['default' => 'IMMUTABLE_EVIDENCE'])]
    private DocumentRetentionClass $retentionClass = DocumentRetentionClass::IMMUTABLE_EVIDENCE;

    #[ORM\Column(name: 'source_key', length: 120, nullable: true)]
    private ?string $sourceKey = null;

    #[ORM\Column(name: 'input_fingerprint', length: 64, nullable: true, options: ['fixed' => true])]
    private ?string $inputFingerprint = null;

    public function __construct(
        string $documentType,
        string $filename,
        string $content,
        string $contentType = 'application/pdf',
        DocumentRetentionClass $retentionClass = DocumentRetentionClass::IMMUTABLE_EVIDENCE,
        ?string $sourceKey = null,
        ?string $inputFingerprint = null,
    ) {
        $this->retentionClass   = $retentionClass;
        $this->sourceKey        = $sourceKey !== null ? mb_substr($sourceKey, 0, 120) : null;
        $this->inputFingerprint = $inputFingerprint;
        $this->documentType = mb_substr($documentType, 0, 40);
        $this->filename     = mb_substr($filename, 0, 255);
        $this->content      = $content;
        $this->sha256       = hash('sha256', $content);
        $this->byteSize     = strlen($content);
        $this->contentType  = $contentType;
        $this->createdAt    = new \DateTimeImmutable();
    }

    public function getId(): ?int { return $this->id; }
    public function getDocumentType(): string { return $this->documentType; }
    public function getFilename(): string { return $this->filename; }
    public function getSha256(): string { return $this->sha256; }
    public function getByteSize(): int { return $this->byteSize; }
    public function getContentType(): string { return $this->contentType; }
    public function getCreatedAt(): \DateTimeImmutable { return $this->createdAt; }
    public function getRetentionClass(): DocumentRetentionClass { return $this->retentionClass; }
    public function getSourceKey(): ?string { return $this->sourceKey; }
    public function getInputFingerprint(): ?string { return $this->inputFingerprint; }

    public function getContent(): string
    {
        return is_resource($this->content) ? (string) stream_get_contents($this->content, -1, 0) : (string) $this->content;
    }
}
